<?php
declare(strict_types=1);
namespace EPejabat\Modules\Training;
use EPejabat\Core\{Database,Core,MasterData,Audit,Authorization};
final class Programmes {
 private static function enum(mixed $v,array $allowed):string {if(!is_string($v)||!in_array($v,$allowed,true))throw new \InvalidArgumentException('Pilihan program tidak sah.');return $v;}
 private static function date(mixed $v):string {$v=Core::text($v,19);$v=str_replace('T',' ',$v);if(strlen($v)===16)$v.=':00';$d=\DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v,new \DateTimeZone('UTC'));if(!$d||$d->format('Y-m-d H:i:s')!==$v)throw new \InvalidArgumentException('Tarikh/masa tidak sah.');return $v;}
 public static function validate(\PDO $p,array $d):array {
  $c=[];foreach(['title'=>190,'organiser'=>190,'co_organiser'=>190,'venue'=>500,'objectives'=>3000,'target_description'=>1000,'tentative'=>5000] as $k=>$max)$c[$k]=Core::text($d[$k]??'',$max,in_array($k,['title','organiser'],true));
  $c['type']=self::enum($d['type']??'COURSE',['COURSE','CME','WORKSHOP','SEMINAR','WEBINAR','CONFERENCE']);$c['classification']=self::enum($d['classification']??'NONE',['NONE','GENERIC','FUNCTIONAL']);$c['mode']=self::enum($d['mode']??'PHYSICAL',['PHYSICAL','ONLINE','HYBRID']);$c['scope']=self::enum($d['scope']??'INTERNAL',['INTERNAL','TARGETED','DISTRICT_WIDE']);$c['registration_mode']=self::enum($d['registration_mode']??'OPEN',['OPEN','TARGETED','INVITATION_ONLY','ADMIN_ASSIGNED']);$c['approval_mode']=self::enum($d['approval_mode']??'AUTO',['AUTO','ADMIN']);
  $c['timezone']=Core::text($d['timezone']??'Asia/Kuala_Lumpur',64);if(!in_array($c['timezone'],\DateTimeZone::listIdentifiers(),true))throw new \InvalidArgumentException('Timezone tidak sah.');
  foreach(['start_at','end_at','open_at','close_at'] as $k)$c[$k]=self::date($d[$k]??'');if($c['start_at']>=$c['end_at']||$c['open_at']>=$c['close_at']||$c['close_at']>$c['end_at'])throw new \InvalidArgumentException('Turutan tarikh tidak sah.');
  $c['capacity']=Core::id($d['capacity']??'');if($c['capacity']>100000)throw new \InvalidArgumentException('Kapasiti maksimum 100000.');
  $hours=$d['effective_hours']??'0';if(!is_scalar($hours)||!is_numeric($hours)||$hours<0||$hours>10000)throw new \InvalidArgumentException('Jam efektif tidak sah.');$c['effective_hours']=(float)$hours;
  foreach(['waiting_list','walkin_enabled'] as $k){$v=$d[$k]??'0';if(!in_array((string)$v,['0','1'],true))throw new \InvalidArgumentException('Flag tidak sah.');$c[$k]=(int)$v;}
  $url=Core::text($d['online_url']??'',500,false);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null))throw new \InvalidArgumentException('Pautan online mesti HTTPS.');$c['online_url']=$url;
  $co=Core::id($d['coordinator_id']??null,true);if($co&&!Database::query($p,'SELECT 1 FROM users WHERE id=? AND is_active=1',[$co])->fetchColumn())throw new \InvalidArgumentException('Penyelaras tidak aktif.');$c['coordinator_id']=$co;
  $c['audience']=[];foreach($d['audience']??[] as $id){$id=Core::id($id);if(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND is_active=1',[$id])->fetchColumn())throw new \InvalidArgumentException('Audience tidak sah.');$c['audience'][]=$id;}$c['audience']=array_values(array_unique($c['audience']));if(count($c['audience'])>200||($c['scope']==='TARGETED'||$c['registration_mode']==='TARGETED')&&!$c['audience'])throw new \InvalidArgumentException('Audience sasaran diperlukan.');
  $c['eligibility']=[];foreach(['profession','position','grade','employment_status'] as $category){$ids=$d['eligibility'][$category]??[];if(!is_array($ids)||count($ids)>100)throw new \InvalidArgumentException('Syarat kelayakan tidak sah.');$c['eligibility'][$category]=[];foreach($ids as $id)$c['eligibility'][$category][]=MasterData::validate($p,Core::id($id),$category);$c['eligibility'][$category]=array_values(array_unique($c['eligibility'][$category]));}
  $c['quotas']=[];foreach($d['quotas']??[] as $q){$kind=self::enum($q['kind']??'',['clinic','unit','profession']);$id=Core::id($q['id']??'');$limit=Core::id($q['limit']??'');if($limit>$c['capacity'])throw new \InvalidArgumentException('Kuota melebihi kapasiti.');if($kind==='profession')MasterData::validate($p,$id,'profession');elseif(!Database::query($p,'SELECT 1 FROM organisations WHERE id=? AND type=? AND is_active=1',[$id,$kind])->fetchColumn())throw new \InvalidArgumentException('Organisasi kuota tidak sah.');$key=$kind.':'.$id;if(isset($c['quotas'][$key]))throw new \InvalidArgumentException('Kuota berulang.');$c['quotas'][$key]=['kind'=>$kind,'id'=>$id,'limit'=>$limit];}if(count($c['quotas'])>200)throw new \InvalidArgumentException('Terlalu banyak kuota.');$c['quotas']=array_values($c['quotas']);return $c;
 }
 public static function save(\PDO $p,int $u,array $d,?int $id=null):int {
  $c=self::validate($p,$d);if($c['coordinator_id']){ $sid=Database::query($p,'SELECT staff_identity_id FROM users WHERE id=?',[$c['coordinator_id']])->fetchColumn();\EPejabat\Core\Staff::get($p,$u,(int)$sid); }return Core::tx($p,function()use($p,$u,$d,$id,$c){
   if($id){$r=Policy::programme($p,$id,true);Policy::require($p,$u,'programmes.edit',$r);if($r['is_cancelled']||in_array($r['status'],['SUBMITTED','UNDER_REVIEW'],true))throw new \RuntimeException('Tarik balik/selesaikan semakan dahulu.');if(isset($d['owner_organisation_id'])&&(int)$d['owner_organisation_id']!==(int)$r['owner_organisation_id'])throw new \RuntimeException('Pemilikan program tidak boleh ditukar melalui edit.');$before=Policy::config($p,$r);
   }else{$org=Core::id($d['owner_organisation_id']??'');Policy::create($p,$u,$org);Database::query($p,'INSERT INTO training_programmes(public_key,owner_organisation_id,created_by) VALUES(?,?,?)',[bin2hex(random_bytes(16)),$org,$u]);$id=(int)$p->lastInsertId();$r=Policy::programme($p,$id,true);$before=null;foreach(['participant'=>'Participant','organiser'=>'Organiser','committee'=>'Committee','speaker'=>'Speaker','facilitator'=>'Facilitator','moderator'=>'Moderator','secretariat'=>'Secretariat','session_chair'=>'Session Chair'] as $code=>$name)Database::query($p,'INSERT INTO training_participation_roles(programme_id,code,name) VALUES(?,?,?)',[$id,$code,$name]);}
   $n=(int)Database::query($p,'SELECT COALESCE(MAX(revision_no),0)+1 FROM training_revisions WHERE programme_id=?',[$id])->fetchColumn();Database::query($p,'INSERT INTO training_revisions(programme_id,revision_no,config_json,created_by) VALUES(?,?,?,?)',[$id,$n,json_encode($c,JSON_THROW_ON_ERROR),$u]);$rev=(int)$p->lastInsertId();Database::query($p,"UPDATE training_programmes SET current_revision_id=?,status='DRAFT' WHERE id=?",[$rev,$id]);Audit::record($p,'programme.saved',$u,(int)$r['owner_organisation_id'],(string)$id,'training','New immutable revision',$before,$c);return $id;
  });
 }
 public static function transition(\PDO $p,int $u,int $id,string $decision,int $revision,string $reason):void {
  $reason=Core::text($reason,500);Core::tx($p,function()use($p,$u,$id,$decision,$revision,$reason){$r=Policy::programme($p,$id,true);$c=Policy::config($p,$r);if($revision!==(int)$r['current_revision_id'])throw new \RuntimeException('Versi berubah; muat semula.');$before=['status'=>$r['status'],'published'=>$r['is_published']];
   if($decision==='SUBMIT'){Policy::require($p,$u,'programmes.submit',$r);if(!in_array($r['status'],['DRAFT','RETURNED'],true))throw new \RuntimeException('Status tidak boleh dihantar.');$status='SUBMITTED';}
   elseif(in_array($decision,['UNDER_REVIEW','APPROVE','RETURN','REJECT'],true)){Policy::require($p,$u,'approvals.review',$r);if(!in_array($r['status'],['SUBMITTED','UNDER_REVIEW'],true))throw new \RuntimeException('Program bukan dalam semakan.');$author=Database::query($p,'SELECT created_by FROM training_revisions WHERE id=?',[$revision])->fetchColumn();if((int)$author===$u&&!Authorization::super($p,$u))throw new \RuntimeException('Kelulusan sendiri tidak dibenarkan.');if($c['scope']==='DISTRICT_WIDE'){$pkd=self::district($p,(int)$r['owner_organisation_id']);if(!$pkd||!Authorization::super($p,$u)&&!Authorization::allowed($p,$u,'training.approvals.review',$pkd))throw new \RuntimeException('Kelulusan scope PKD diperlukan.');}foreach($c['audience'] as $o)if(!Authorization::super($p,$u)&&!Authorization::allowed($p,$u,'training.approvals.review',$o))throw new \RuntimeException('Kelulusan melampaui scope diperlukan.');$status=['UNDER_REVIEW'=>'UNDER_REVIEW','APPROVE'=>'APPROVED','RETURN'=>'RETURNED','REJECT'=>'REJECTED'][$decision];if($decision==='APPROVE')Database::query($p,'UPDATE training_programmes SET approved_revision_id=? WHERE id=?',[$revision,$id]);}
   elseif($decision==='PUBLISH'){Policy::require($p,$u,'programmes.publish',$r);if($r['status']!=='APPROVED'||(int)$r['approved_revision_id']!==$revision||$r['is_cancelled'])throw new \RuntimeException('Versi belum diluluskan.');Registration::verifyCapacity($p,$id,$c);Database::query($p,'UPDATE training_programmes SET published_revision_id=?,is_published=1 WHERE id=?',[$revision,$id]);$status='APPROVED';}
   elseif($decision==='UNPUBLISH'||$decision==='CANCEL'){Policy::require($p,$u,'programmes.publish',$r);Database::query($p,'UPDATE training_programmes SET is_published=0,is_cancelled=? WHERE id=?',[$decision==='CANCEL'?1:0,$id]);if($decision==='CANCEL'){foreach(Database::query($p,"SELECT * FROM training_registrations WHERE programme_id=? AND status IN ('PENDING','CONFIRMED','WAITLISTED') FOR UPDATE",[$id])->fetchAll() as $reg)Registration::change($p,$r,$reg,$u,'CANCELLED',$reason);} $status=$r['status'];}
   else throw new \InvalidArgumentException('Tindakan tidak sah.');Database::query($p,'UPDATE training_programmes SET status=? WHERE id=?',[$status,$id]);Database::query($p,'INSERT INTO training_approvals(programme_id,revision_id,actor_id,decision,reason) VALUES(?,?,?,?,?)',[$id,$revision,$u,$decision,$reason]);Audit::record($p,'programme.'.strtolower($decision),$u,(int)$r['owner_organisation_id'],(string)$id,'training',$reason,$before,['status'=>$status,'revision'=>$revision]);
  });
 }
 public static function district(\PDO $p,int $org):?int {$v=Database::query($p,"SELECT o.id FROM organisations o JOIN organisation_hierarchy h ON h.ancestor_id=o.id WHERE h.descendant_id=? AND o.type='pkd' AND o.is_active=1 ORDER BY h.depth LIMIT 1",[$org])->fetchColumn();return $v?(int)$v:null;}
}
